video.script:
(function(){
  try {
    var doc = document;
    var m = doc.documentElement.outerHTML.match(/playData\(\s*['"]([A-Za-z0-9+/=]+)['"]\s*,\s*['"]([0-9a-f]+)['"]\s*\)/);
    if (typeof playData === 'function' && m) {
      var url = playData(m[1], m[2]);
      if (url && /^https?:\/\/.+\.(m3u8|mp4|webm)/i.test(url)) return url;
    }
    var f = doc.querySelector('iframe#MacPlayer, iframe#buffer, iframe[src*="/player/"]');
    var src = (f && f.getAttribute('src')) || '';
    if (!src) {
      var ifs = doc.querySelectorAll('iframe');
      for (var i = 0; i < ifs.length; i++) {
        var s = ifs[i].getAttribute('src') || '';
        if (/player|v2player|cfhls/i.test(s)) { src = s; break; }
      }
    }
    if (src && /\/player\/\?url=/.test(src)) {
      return 'webview:' + (src.indexOf('http') === 0 ? src : location.origin + src);
    }
    var v = doc.querySelector('video[src]');
    if (v && v.getAttribute('src')) return v.getAttribute('src');
    return '';
  } catch (e) { return ''; }
})();
